interface CreditCardProps {
  variant: "black" | "red" | "galaxy";
  index: number;
  width: number;
  bankName: string;
  holderName: string;
  colors: { primary: string; secondary?: string };
  animValues: { rotate: number; x: number; y: number; scale: number; opacity: number };
}

const CreditCard: React.FC<CreditCardProps> = ({
  variant,
  index,
  width,
  bankName,
  holderName,
  colors,
  animValues,
}) => {
  const cardWidth = width * 0.35; // Responsive card width
  const cardHeight = cardWidth / 1.586; // Standard Aspect Ratio

  const baseStyle: React.CSSProperties = {
    width: cardWidth,
    height: cardHeight,
    borderRadius: cardWidth * 0.05,
    position: "absolute",
    top: "50%",
    left: "50%",
    boxShadow: "0 20px 40px rgba(0,0,0,0.4)",
    transform: `translate(-50%, -50%) translate(${animValues.x}px, ${animValues.y}px) rotate(${animValues.rotate}deg) scale(${animValues.scale})`,
    opacity: animValues.opacity,
    zIndex: index,
    overflow: "hidden",
    display: "flex",
    flexDirection: "column",
    padding: cardWidth * 0.06,
    justifyContent: "space-between",
    color: "white",
    fontFamily: "Plus Jakarta Sans, sans-serif",
    border: "1px solid rgba(255,255,255,0.1)",
    backfaceVisibility: "hidden",
  };

  const getBackground = () => {
    if (variant === "black") return colors.primary;
    if (variant === "red") return `linear-gradient(110deg, ${colors.primary} 0%, ${colors.secondary} 100%)`;
    if (variant === "galaxy") return `radial-gradient(circle at 30% 0%, #3a3a3a 0%, ${colors.primary} 100%)`;
    return colors.primary;
  };

  return (
    <div style={{ ...baseStyle, background: getBackground() }}>
      {/* Texture for Galaxy Card */}
      {variant === "galaxy" && (
        <>
          <Star top="15%" left="40%" size={20} opacity={0.6} />
          <Star top="40%" left="20%" size={14} opacity={0.4} />
          <Star top="25%" left="60%" size={10} opacity={0.3} />
          <Star top="60%" left="50%" size={24} opacity={0.1} />
        </>
      )}

      {/* Shine/Gloss Effect */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "linear-gradient(125deg, rgba(255,255,255,0.15) 0%, rgba(255,255,255,0) 40%)",
          pointerEvents: "none",
        }}
      />

      {/* Top Row: Bank Name & Logo */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div style={{ fontSize: cardWidth * 0.05, fontWeight: 700 }}>
          {variant === "galaxy" ? "Galaxy" : bankName}
          {variant === "galaxy" && <div style={{ fontSize: "0.5em", fontWeight: 400, opacity: 0.8, letterSpacing: 2 }}>PREMIUM</div>}
        </div>
        <Logo />
      </div>

      {/* Chip & Contactless */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: cardHeight * 0.05 }}>
        <Chip />
        {variant === "galaxy" && <ContactlessIcon />}
      </div>

      {/* Card Number */}
      <div
        style={{
          fontSize: cardWidth * 0.065,
          fontFamily: "Share Tech Mono, monospace",
          letterSpacing: 2,
          marginTop: cardHeight * 0.02,
          textShadow: "0 2px 4px rgba(0,0,0,0.5)",
        }}
      >
        {variant === "galaxy" ? "1234 6789 8761 0000" : "**** **** **** 8761"}
      </div>

      {/* Bottom Row: Holder & Expiry */}
      <div style={{ display: "flex", justifyContent: "space-between", marginTop: "auto", fontSize: cardWidth * 0.035 }}>
        <div>
          <div style={{ fontSize: "0.7em", opacity: 0.7, textTransform: "uppercase" }}>Card Holder</div>
          <div style={{ fontWeight: 600, marginTop: 2 }}>{holderName.toUpperCase()}</div>
        </div>
        <div>
          <div style={{ fontSize: "0.7em", opacity: 0.7, textTransform: "uppercase" }}>Valid Thru</div>
          <div style={{ fontWeight: 600, marginTop: 2 }}>06/30</div>
        </div>
      </div>
    </div>
  );
};

// --- Main Composition ---

const FanningCards: React.FC<FanningCardsProps> = ({
  backgroundColor = "#f0eff4",
  transparentBackground = false,
  durationInSeconds = 5,
  bankName = "Finfirst Bank",
  holderName = "Sarah Williams",
  card1Color = "#1a1a1a",
  card2PrimaryColor = "#a6262e",
  card2SecondaryColor = "#1a1a1a",
  card3Color = "#0f0f0f",
}) => {
  useFontLoader(["Plus Jakarta Sans", "Share Tech Mono"]);
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Constants
  const entranceDelay = 10;
  
  // Calculate animation values for each card
  const getCardAnim = (index: number, targetRot: number, targetX: number, targetY: number, delayFrames: number) => {
    // Reveal (Scale/Fade in)
    const scale = spring({
      frame: frame - delayFrames,
      fps,
      config: { stiffness: 80, damping: 15 },
      from: 0.5,
      to: 1,
    });
    
    const opacity = spring({
      frame: frame - delayFrames,
      fps,
      config: { stiffness: 100, damping: 20 },
      from: 0,
      to: 1,
    });

    // Fan Out Motion
    const fanProgress = spring({
      frame: frame - delayFrames - 20, // Start fanning after appearing
      fps,
      config: { mass: 0.8, stiffness: 60, damping: 12 },
    });

    const rotate = interpolate(fanProgress, [0, 1], [-5, targetRot]); // Start slightly tilted together
    const x = interpolate(fanProgress, [0, 1], [0, targetX]);
    const y = interpolate(fanProgress, [0, 1], [0, targetY]);

    return { scale, opacity, rotate, x, y };
  };

  // Card Configurations
  // The offsets are relative to center. 
  // Card 1 (Back/Left): Rotated Left (-15deg), Offset Left/Up
  const card1Anim = getCardAnim(0, -18, -width * 0.08, -height * 0.08, entranceDelay);

  // Card 2 (Middle): Almost straight, slightly right (5deg)
  const card2Anim = getCardAnim(1, 4, 0, -height * 0.02, entranceDelay + 5);

  // Card 3 (Front/Right): Rotated Right (20deg), Offset Right/Down
  const card3Anim = getCardAnim(2, 22, width * 0.08, height * 0.08, entranceDelay + 10);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Background Gradient for Aesthetics if not transparent */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            background: `radial-gradient(circle at 50% 50%, rgba(255,255,255,0.8) 0%, ${backgroundColor} 100%)`,
            zIndex: 0,
          }}
        />
      )}

      <div style={{ position: "relative", width: "100%", height: "100%", zIndex: 1 }}>
        
        {/* Card 1: Bottom/Back */}
        <CreditCard
          index={1}
          variant="black"
          width={width}
          bankName={bankName}
          holderName={holderName}
          colors={{ primary: card1Color }}
          animValues={card1Anim}
        />

        {/* Card 2: Middle */}
        <CreditCard
          index={2}
          variant="red"
          width={width}
          bankName={bankName}
          holderName={holderName}
          colors={{ primary: card2PrimaryColor, secondary: card2SecondaryColor }}
          animValues={card2Anim}
        />

        {/* Card 3: Top/Front */}
        <CreditCard
          index={3}
          variant="galaxy"
          width={width}
          bankName={bankName}
          holderName={holderName}
          colors={{ primary: card3Color }}
          animValues={card3Anim}
        />
      </div>
    </AbsoluteFill>
  );
};

export default FanningCards;